class FreqStack {
public:
    FreqStack() {

    }

    void push(int val) {
        freq[val]++;
        max_freq = max(max_freq, freq[val]);
        stacks[freq[val]].push(val);
    }

    int pop() {
        int val = stacks[max_freq].top();
        stacks[max_freq].pop();
        freq[val]--;
        if (stacks[max_freq].empty()) {
            max_freq--;
        }
        return val;
    }

