class Solution {
public:
    string reverseWords(string s) {
        int n = s.size();
        int left = 0, right = n - 1;
        while (left < n && s[left] == ' ') ++left;
        while (right >= 0 && s[right] == ' ') --right;
        if (left > right) return "";

        string res;
        int i = right;
        while (i >= left) {
            while (i >= left && s[i] == ' ') --i;
            int j = i;
            while (j >= left && s[j] != ' ') --j;
            if (i >= left) {
                res += s.substr(j + 1, i - j);
                if (j >= left) res += ' ';
            }
            i = j;
        }
        return res;
    }
};

