class Solution {
    public int superEggDrop(int k, int n) {
        int[][] dp = new int[k + 1][n + 1];
        for (int j = 1; j <= n; j++) dp[1][j] = j;
        for (int i = 2; i <= k; i++) {
            int x = 1;
            for (int j = 1; j <= n; j++) {
                while (x < j && dp[i][x] < dp[i - 1][j - x]) x++;
                dp[i][j] = 1 + dp[i - 1][x - 1];
                if (x < j) dp[i][j] = Math.min(dp[i][j], 1 + dp[i][j - x]);
            }
        }
        return dp[k][n];
    }
}

