class Solution:
    def minimumSteps(self, s: str) -> int:
        left = 0
        right = len(s) - 1
        steps = 0
        while left < right:
            if s[left] == '1':
                left += 1
            elif s[right] == '0':
                right -= 1
            else:
                while left < right and s[left] == '1':
                    left += 1
                while left < right and s[right] == '0':
                    right -= 1
                steps += 1
        return steps

class Solution:
    def baseNeg2(self, n: int) -> str:
        result = ""
        while n > 0:
            result = str(n % 2) + result
            n //= 2
        return result[::-1]

class Solution:
    def reachNumber(self, target: int) -> int:
        target = abs(target)
        k = 0
        while target > 0:
            k += 1
            target -= k
        if target > 0:
            return k + 1
        return k
